import { createContext, useContext, useState } from 'react';

// 1. Creamos el Contexto
const UserContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState({ name: 'Juan', role: 'ADMIN' });

  return (
    // 2. Proveemos el dato a toda la App
    <UserContext.Provider value={{ user, setUser }}>
      {children}
    </UserContext.Provider>
  );
};

// 3. Hook para consumirlo fácilmente
export const useAuth = () => useContext(UserContext);

// hooks/useClientes.js
import { useState, useEffect } from 'react';

export const useClientes = () => {
  const [clientes, setClientes] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch('http://localhost:8080/api/clientes')
      .then(res => res.json())
      .then(data => {
        setClientes(data);
        setLoading(false);
      });
  }, []);

  return { clientes, loading };
};

import { useClientes } from '../hooks/useClientes';

export const TablaClientes = () => {
  // Extraemos la magia en 1 línea
  const { clientes, loading } = useClientes();

  if (loading) return <p>Cargando datos desde Java...</p>;

  return (
    <table>
      {clientes.map(cli => (
        <tr key={cli.id}>
          <td>{cli.nombreCompleto}</td>
        </tr>
      ))}
    </table>
  );
};

